typedef long long ll;

static int upper_bound_ll(ll *a, int n, ll x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (a[m] <= x) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N, Q;
    ll K;
    if (scanf("%d %lld %d", &N, &K, &Q) != 3) return 0;

    ll *X = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &X[i]);

    /* nxt[i]: first index j > i such that X[j] - X[i] >= K, or N if none */
    int *nxt = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        ll target = X[i] + K;
        nxt[i] = upper_bound_ll(X, N, target - 1); /* first X[j] >= target */
    }

    /*
      dp[i] = maximum size of a good set using only points i..(R fixed later)
      For a fixed query [L, R], classic recurrence:
        f(i) = max(1 + f(nxt[i]), f(i+1)) for i <= R
        f(R+1) = 0

      We need size of union of all maximum-cardinality solutions.
      A point i belongs to some optimal solution iff:
        1 + f(nxt[i]) == f(i)
      when computed on interval [L, R].

      We process each query directly in O(len).
    */

    int *f = (int *)malloc(sizeof(int) * (N + 1));

    while (Q--) {
        int L, R;
        scanf("%d %d", &L, &R);
        L--, R--;

        f[R + 1] = 0;
        for (int i = R; i >= L; i--) {
            int take = 1;
            if (nxt[i] <= R) take += f[nxt[i]];
            int skip = f[i + 1];
            f[i] = (take > skip ? take : skip);
        }

        int ans = 0;
        for (int i = L; i <= R; i++) {
            int take = 1;
            if (nxt[i] <= R) take += f[nxt[i]];
            if (take == f[i]) ans++;
        }

        printf("%d\n", ans);
    }

    free(X);
    free(nxt);
    free(f);
    return 0;
}

