int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    long long K;
    cin >> N >> K >> Q;

    vector<long long> X(N + 1);
    for (int i = 1; i <= N; ++i) cin >> X[i];

    // nxt[i] = smallest j > i such that X[j] - X[i] >= K, or N+1 if none
    vector<int> nxt(N + 2, N + 1);
    int p = 1;
    for (int i = 1; i <= N; ++i) {
        if (p < i + 1) p = i + 1;
        while (p <= N && X[p] - X[i] < K) ++p;
        nxt[i] = p;
    }

    // dp[i] = maximum size of a good set using points from [i..N]
    vector<int> dp(N + 2, 0);
    for (int i = N; i >= 1; --i) {
        dp[i] = max(dp[i + 1], 1 + (nxt[i] <= N ? dp[nxt[i]] : 0));
    }

    // take[i] = whether there exists an optimal solution on suffix [i..N] that takes i
    vector<char> take(N + 2, 0);
    for (int i = 1; i <= N; ++i) {
        int valTake = 1 + (nxt[i] <= N ? dp[nxt[i]] : 0);
        if (valTake == dp[i]) take[i] = 1;
    }

    // Binary lifting on nxt
    int LOG = 1;
    while ((1 << LOG) <= N + 1) ++LOG;
    vector<vector<int>> up(LOG, vector<int>(N + 2, N + 1));
    for (int i = 1; i <= N + 1; ++i) up[0][i] = (i <= N ? nxt[i] : N + 1);
    for (int b = 1; b < LOG; ++b) {
        for (int i = 1; i <= N + 1; ++i) {
            int mid = up[b - 1][i];
            up[b][i] = (mid <= N ? up[b - 1][mid] : N + 1);
        }
    }

    auto jump = [&](int start, int steps) {
        int v = start;
        for (int b = 0; b < LOG; ++b) {
            if (steps & (1 << b)) {
                v = up[b][v];
                if (v == N + 1) break;
            }
        }
        return v;
    };

    while (Q--) {
        int L, R;
        cin >> L >> R;

        // Greedy from L gives one maximum set in interval [L, R]
        // cnt = max size in [L, R]
        int cur = L;
        int cnt = 0;
        for (int b = LOG - 1; b >= 0; --b) {
            int to = cur;
            int steps = 1 << b;
            // simulate taking 'steps' points starting from cur
            for (int bb = 0; bb < LOG; ++bb) {
                if (steps & (1 << bb)) {
                    to = up[bb][to];
                    if (to == N + 1) break;
                }
            }
            // after taking steps points, last next-position is 'to'
            // valid iff all chosen points are <= R, i.e. position after steps-1 jumps starts from <=R
            // Easier approach: test the point after (steps-1) jumps.
            int lastStart = jump(cur, steps - 1);
            if (lastStart <= R) {
                cnt += steps;
                cur = (lastStart <= N ? nxt[lastStart] : N + 1);
            }
        }

        // Union of all maximum sets in [L,R]:
        // A point i belongs to some optimal set iff:
        // 1) i in [L,R]
        // 2) there exists optimal prefix on [L..i] ending at i and
        // 3) there exists optimal suffix on [i..R] starting at i
        //
        // For interval version, compute:
        // leftCnt[i] = max picks in [L..i]
        // rightCnt from i similarly is greedy count starting at i within R.
        //
        // Since all maximum independent sets on interval graph of points with threshold K
        // form a greedoid-like structure, a point i is in some maximum set iff
        // gL(i) + gR(i) - 1 == cnt,
        // where gL(i) = maximum size of valid set in [L..i] that must include i,
        // and gR(i) = maximum size of valid set in [i..R] that must include i.
        //
        // We compute these by greedy predecessor/successor counts.

        // Build predecessor with two pointers on demand for this query range.
        // Since constraints are not provided here, use O(length log N) per query robustly.
        int ans = 0;

        // For each i in [L,R], compute:
        // left = maximum picks ending at i = 1 + maximum picks ending at predecessor chain
        // But for sorted points with spacing constraint, greedy is unique in count:
        // leftInclude = max number of selected points in [L..i] including i
        // equals 1 + max number in [L..pred(i)], where pred(i) is largest j < i with X[i]-X[j] >= K.
        //
        // We'll precompute pred for all i by two pointers globally.
        static vector<int> pred;
        static bool predBuilt = false;
        if (!predBuilt) {
            pred.assign(N + 2, 0);
            int j = 0;
            for (int i = 1; i <= N; ++i) {
                while (j + 1 < i && X[i] - X[j + 1] >= K) ++j;
                pred[i] = j;
            }
            predBuilt = true;
        }

        vector<int> leftDP(R - L + 2, 0), leftInc(R - L + 2, 0);
        // best on [L..idx]
        for (int i = L; i <= R; ++i) {
            int pos = i - L + 1;
            int pidx = pred[i];
            int inc = 1;
            if (pidx >= L) inc += leftDP[pidx - L + 1];
            leftInc[pos] = inc;
            leftDP[pos] = max(leftDP[pos - 1], inc);
        }

        vector<int> rightDP(R - L + 3, 0), rightInc(R - L + 3, 0);
        for (int i = R; i >= L; --i) {
            int pos = i - L + 1;
            int ni = nxt[i];
            int inc = 1;
            if (ni <= R) inc += rightDP[ni - L + 1];
            rightInc[pos] = inc;
            rightDP[pos] = max(rightDP[pos + 1], inc);
        }

        int best = leftDP[R - L + 1];
        for (int i = L; i <= R; ++i) {
            int pos = i - L + 1;
            if (leftInc[pos] + rightInc[pos] - 1 == best) ++ans;
        }

        cout << ans << '\n';
    }

    return 0;
}
